@using sv_052870c551434a079a749d6ed8614315.Models
@inject IJSRuntime JS
@implements IAsyncDisposable

<div class="message-panel">
    @if (Channel is not null)
    {
        <div class="panel-header">
            <h2># @Channel.Name</h2>
            <p class="channel-description">@Channel.Description</p>
        </div>

        <div class="message-list" @ref="_messageListRef" @onscroll="HandleScroll">
            @if (_loadingMore)
            {
                <div class="loading-indicator">Loading older messages...</div>
            }
            @if (!HasMoreMessages && Messages.Count > 0)
            {
                <div class="beginning-indicator">Beginning of channel history</div>
            }
            @foreach (var message in Messages)
            {
                <MessageItem Message="message"
                             IsThreadStarter="message.ReplyToId is null"
                             ReplyCount="GetReplyCount(message.Id)"
                             OnOpenThread="() => OnOpenThread.InvokeAsync(message.Id)"
                             OnReact="(emoji) => OnReact.InvokeAsync((message.Id, emoji))" />
            }
        </div>

        <MessageInput Placeholder="@($"Message #{Channel.Name}")"
                      ButtonLabel="Send"
                      OnSubmit="HandleSend" />
    }
    else
    {
        <div class="no-channel-selected">
            <p>Select a channel to start chatting</p>
        </div>
    }
