@using sv_052870c551434a079a749d6ed8614315.Models

<div class="channel-sidebar">
    <div class="sidebar-header">
        <h3>Channels</h3>
    </div>
    <div class="channel-list">
        @foreach (var channel in Channels)
        {
            <ChannelItem Channel="channel"
                         IsActive="channel.Id == ActiveChannelId"
                         OnClick="() => OnChannelSelected.InvokeAsync(channel.Id)" />
        }
    </div>
</div>

@code {
    [Parameter] public List<Channel> Channels { get; set; } = [];
    [Parameter] public int ActiveChannelId { get; set; }
    [Parameter] public EventCallback<int> OnChannelSelected { get; set; }
}

@using sv_052870c551434a079a749d6ed8614315.Models
@inject IJSRuntime JS
@implements IAsyncDisposable

<div class="message-panel">
    @if (Channel is not null)
    {
        <div class="panel-header">
            <h2># @Channel.Name</h2>
            <p class="channel-description">@Channel.Description</p>
        </div>

        <div class="message-list" @ref="_messageListRef" @onscroll="HandleScroll">
            @if (_loadingMore)
            {
                <div class="loading-indicator">Loading older messages...</div>
            }
            @if (!HasMoreMessages && Messages.Count > 0)
            {
                <div class="beginning-indicator">Beginning of channel history</div>
            }
            @foreach (var message in Messages)
            {
                <MessageItem Message="message"
                             IsThreadStarter="message.ReplyToId is null"
                             ReplyCount="GetReplyCount(message.Id)"
                             OnOpenThread="() => OnOpenThread.InvokeAsync(message.Id)"
                             OnReact="(emoji) => OnReact.InvokeAsync((message.Id, emoji))" />
            }
        </div>

        <MessageInput Placeholder="@($"Message #{Channel.Name}")"
                      ButtonLabel="Send"
                      OnSubmit="HandleSend" />
    }
    else
    {
        <div class="no-channel-selected">
            <p>Select a channel to start chatting</p>
        </div>
    }
</div>

@code {
    [Parameter] public Channel? Channel { get; set; }
    [Parameter] public List<Message> Messages { get; set; } = [];
    [Parameter] public List<ThreadSummary> ThreadSummaries { get; set; } = [];
    [Parameter] public bool HasMoreMessages { get; set; } = true;
    [Parameter] public EventCallback<int> OnOpenThread { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }
    [Parameter] public EventCallback<string> OnSendMessage { get; set; }
    [Parameter] public EventCallback OnLoadMore { get; set; }

    private ElementReference _messageListRef;
    private DotNetObjectReference<MessagePanel>? _dotNetRef;
    private bool _loadingMore;
    private bool _shouldScrollToBottom = true;

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (_shouldScrollToBottom)
        {
            _shouldScrollToBottom = false;
            await ScrollToBottom();
        }
    }

    private async Task ScrollToBottom()
    {
        try
        {
            await JS.InvokeVoidAsync("eval",
                "document.querySelector('.message-list')?.scrollTo(0, document.querySelector('.message-list')?.scrollHeight ?? 0)");
        }
        catch (JSDisconnectedException) { }
    }

    private async Task HandleScroll()
    {
        if (_loadingMore || !HasMoreMessages) return;

        try
        {
            var scrollTop = await JS.InvokeAsync<double>("eval",
                "document.querySelector('.message-list')?.scrollTop ?? 1");

            if (scrollTop < 50)
            {
                _loadingMore = true;
                StateHasChanged();
                await OnLoadMore.InvokeAsync();
                _loadingMore = false;
            }
        }
        catch (JSDisconnectedException) { }
    }

    private int GetReplyCount(int messageId)
    {
        return ThreadSummaries.FirstOrDefault(t => t.RootMessageId == messageId)?.ReplyCount ?? 0;
    }

    private async Task HandleSend(string content)
    {
        _shouldScrollToBottom = true;
        await OnSendMessage.InvokeAsync(content);
    }

    public void ScrollAfterNewMessage()
    {
        _shouldScrollToBottom = true;
    }

    public ValueTask DisposeAsync()
    {
        _dotNetRef?.Dispose();
        return ValueTask.CompletedTask;
    }
}

