toolArgs.file_text:
/* ── Chat Layout ── */
.chat-layout {
    display: flex;
    height: 100vh;
    overflow: hidden;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    background: #1a1d21;
    color: #d1d2d3;
}

/* ── Channel Sidebar ── */
::deep .channel-sidebar {
    width: 20%;
    min-width: 200px;
    background: #19171d;
    border-right: 1px solid #2c2d30;
    display: flex;
    flex-direction: column;
    overflow: hidden;
}

::deep .sidebar-header {
    padding: 16px 16px 12px;
    border-bottom: 1px solid #2c2d30;
}

::deep .sidebar-header h3 {
    margin: 0;
    font-size: 1.1rem;
    color: #fff;
}

::deep .channel-list {
    flex: 1;
    overflow-y: auto;
    padding: 8px 0;
}

::deep .channel-item {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 6px 16px;
    cursor: pointer;
    border-radius: 6px;
    margin: 0 8px;
    transition: background 0.15s;
}

::deep .channel-item:hover {
    background: #27242c;
}

::deep .channel-item.active {
    background: #1164a3;
    color: #fff;
}

::deep .channel-info {
    display: flex;
    flex-direction: column;
    min-width: 0;
}

::deep .channel-name {
    font-weight: 600;
    font-size: 0.9rem;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

::deep .channel-desc {
    font-size: 0.75rem;
    color: #9ea0a5;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    margin-top: 2px;
}

::deep .channel-item.active .channel-desc {
    color: #c5d5e3;
}

::deep .unread-badge {
    background: #e01e5a;
    color: #fff;
    font-size: 0.7rem;
    font-weight: 700;
    padding: 2px 7px;
    border-radius: 10px;
    margin-left: 8px;
    flex-shrink: 0;
}

/* ── Main Chat Area ── */
.chat-main {
    flex: 1;
    display: flex;
    min-width: 0;
}

.chat-main.thread-visible {
    flex: 0 0 55%;
}

::deep .message-panel {
    flex: 1;
    display: flex;
    flex-direction: column;
    overflow: hidden;
}

::deep .panel-header {
    padding: 12px 20px;
    border-bottom: 1px solid #2c2d30;
    flex-shrink: 0;
}

::deep .panel-header h2 {
    margin: 0;
    font-size: 1.1rem;
    color: #fff;
}

::deep .channel-description {
    margin: 4px 0 0;
    font-size: 0.8rem;
    color: #9ea0a5;
}

::deep .no-channel-selected {
    flex: 1;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #9ea0a5;
}

/* ── Message List ── */
::deep .message-list {
    flex: 1;
    overflow-y: auto;
    padding: 12px 20px;
}

::deep .loading-indicator,
::deep .beginning-indicator {
    text-align: center;
    color: #9ea0a5;
    font-size: 0.8rem;
    padding: 8px 0;
}

/* ── Message Item ── */
::deep .message-item {
    position: relative;
    padding: 8px 12px;
    border-radius: 6px;
    margin-bottom: 2px;
    transition: background 0.15s;
}

::deep .message-item:hover {
    background: #222529;
}

::deep .message-header {
    display: flex;
    align-items: baseline;
    gap: 8px;
    margin-bottom: 2px;
}

::deep .message-author {
    font-weight: 700;
    font-size: 0.9rem;
    color: #fff;
}

::deep .message-time {
    font-size: 0.75rem;
    color: #9ea0a5;
}

::deep .message-content {
    font-size: 0.9rem;
    line-height: 1.46;
    word-wrap: break-word;
}

/* ── Reactions ── */
::deep .reaction-row {
    display: flex;
    flex-wrap: wrap;
    gap: 4px;
    margin-top: 6px;
}

::deep .reaction-badge {
    display: inline-flex;
    align-items: center;
    gap: 4px;
    background: #2c2d30;
    border: 1px solid #3c3d40;
    border-radius: 12px;
    padding: 2px 8px;
    font-size: 0.8rem;
    cursor: pointer;
    color: #d1d2d3;
    transition: background 0.15s;
}

::deep .reaction-badge:hover {
    background: #3c3d40;
    border-color: #4c4d50;
}

/* ── Thread Link ── */
::deep .thread-link {
    background: none;
    border: none;
    color: #1d9bd1;
    font-size: 0.8rem;
    cursor: pointer;
    padding: 4px 0;
    font-weight: 600;
}

::deep .thread-link:hover {
    text-decoration: underline;
}

/* ── Hover Actions ── */
::deep .message-actions {
    position: absolute;
    top: -8px;
    right: 8px;
    display: flex;
    gap: 2px;
    background: #1a1d21;
    border: 1px solid #3c3d40;
    border-radius: 6px;
    padding: 2px;
    box-shadow: 0 2px 8px rgba(0,0,0,0.3);
}

::deep .action-btn {
    background: none;
    border: none;
    padding: 4px 8px;
    cursor: pointer;
    border-radius: 4px;
    font-size: 0.9rem;
    transition: background 0.15s;
}

::deep .action-btn:hover {
    background: #2c2d30;
}

/* ── Emoji Picker ── */
::deep .emoji-picker {
    position: absolute;
    top: -8px;
    right: 80px;
    display: flex;
    gap: 2px;
    background: #1a1d21;
    border: 1px solid #3c3d40;
    border-radius: 6px;
    padding: 4px;
    box-shadow: 0 2px 8px rgba(0,0,0,0.3);
    z-index: 10;
}

::deep .emoji-btn {
    background: none;
    border: none;
    padding: 4px 6px;
    cursor: pointer;
    font-size: 1.1rem;
    border-radius: 4px;
    transition: background 0.15s;
}

::deep .emoji-btn:hover {
    background: #2c2d30;
}

/* ── Message Input ── */
::deep .message-input {
    display: flex;
    gap: 8px;
    padding: 12px 20px;
    border-top: 1px solid #2c2d30;
    flex-shrink: 0;
}

::deep .message-input textarea {
    flex: 1;
    resize: none;
    padding: 10px 12px;
    border-radius: 8px;
    border: 1px solid #3c3d40;
    background: #222529;
    color: #d1d2d3;
    font-size: 0.9rem;
    font-family: inherit;
    outline: none;
    transition: border-color 0.15s;
}

::deep .message-input textarea:focus {
    border-color: #1164a3;
}

::deep .message-input textarea::placeholder {
    color: #7a7b7f;
}

::deep .send-btn {
    padding: 8px 20px;
    background: #007a5a;
    color: #fff;
    border: none;
    border-radius: 8px;
    font-weight: 600;
    font-size: 0.85rem;
